130→func configureDroidRepoSettings(repoDir string) error {
131→	home, err := os.UserHomeDir()
132→	if err != nil {
133→		return fmt.Errorf("get home dir: %w", err)
134→	}
135→
136→	globalSettingsPath := filepath.Join(home, ".factory", "settings.json")
137→	repoSettingsPath := filepath.Join(repoDir, droidRepoSettingsPath)
138→
139→	if err := mergeDroidCustomModels(globalSettingsPath, repoSettingsPath); err != nil {
140→		return err
141→	}
142→	if err := ensureGitInfoExcludeContains(repoDir, droidRepoSettingsPath); err != nil {
143→		return fmt.Errorf("exclude droid settings from git: %w", err)
144→	}
145→	return nil
146→}
147→
148→func mergeDroidCustomModels(globalSettingsPath, repoSettingsPath string) error {
149→	globalSettings, err := loadJSONMap(globalSettingsPath, "global droid settings")
150→	if err != nil {
151→		return err
152→	}
153→
154→	customModels, ok := globalSettings["customModels"]
155→	if !ok {
156→		return fmt.Errorf(
157→			"global droid settings at %s missing customModels; repo-local %s shadows global settings",
158→			globalSettingsPath,
159→			repoSettingsPath,
160→		)
161→	}
162→
163→	var models []json.RawMessage
164→	if err := json.Unmarshal(customModels, &models); err != nil {
165→		return fmt.Errorf("parse customModels in %s: %w", globalSettingsPath, err)
166→	}
167→	if len(models) == 0 {
168→		return fmt.Errorf("global droid settings at %s has empty customModels", globalSettingsPath)
169→	}
170→
171→	repoSettings, err := loadJSONMap(repoSettingsPath, "repo-local droid settings")
172→	if err != nil {
173→		return err
174→	}
175→	repoSettings["customModels"] = customModels
176→
177→	// Set the active custom model so interactive mode uses the BYOK model
178→	// instead of prompting for selection. The value must match the Model
179→	// field from the customModels entry (not the displayName).
180→	modelJSON, err := json.Marshal(agents.DefaultDroidModel())
181→	if err != nil {
182→		return fmt.Errorf("marshal model setting: %w", err)
183→	}
184→	repoSettings["model"] = json.RawMessage(modelJSON)
185→
186→	// High autonomy prevents Droid from asking for confirmation during
187→	// interactive E2E tests, which would cause hangs waiting for input.
188→	repoSettings["autonomyMode"] = json.RawMessage(`"auto-high"`)
189→	repoSettings["completionSound"] = json.RawMessage(`"off"`)
190→
191→	out, err := json.MarshalIndent(repoSettings, "", "  ")
192→	if err != nil {
193→		return fmt.Errorf("marshal repo-local droid settings: %w", err)
194→	}
195→	out = append(out, '\n')
196→
197→	if err := os.WriteFile(repoSettingsPath, out, 0o600); err != nil {
198→		return fmt.Errorf("write repo-local droid settings %s: %w", repoSettingsPath, err)
199→	}
200→	return nil
201→}
202→
203→func loadJSONMap(path, description string) (map[string]json.RawMessage, error) {
204→	data, err := os.ReadFile(path)
205→	if err != nil {
206→		return nil, fmt.Errorf("read %s at %s: %w", description, path, err)
207→	}
208→
209→	var parsed map[string]json.RawMessage
210→	if err := json.Unmarshal(data, &parsed); err != nil {
211→		return nil, fmt.Errorf("parse %s at %s: %w", description, path, err)
212→	}
213→	if parsed == nil {
214→		parsed = make(map[string]json.RawMessage)
215→	}
216→	return parsed, nil
217→}
218→
219→func ensureGitInfoExcludeContains(repoDir, entry string) error {
220→	excludePath := filepath.Join(repoDir, ".git", "info", "exclude")
221→
222→	data, err := os.ReadFile(excludePath)
223→	if err != nil && !errors.Is(err, os.ErrNotExist) {
224→		return fmt.Errorf("read %s: %w", excludePath, err)
225→	}
226→
227→	normalized := strings.ReplaceAll(string(data), "\r\n", "\n")
228→	for _, line := range strings.Split(normalized, "\n") {
229→		if strings.TrimSpace(line) == entry {
230→			return nil
231→		}
232→	}
233→
234→	var b strings.Builder
235→	if len(data) > 0 {
236→		b.Write(data)
237→		if data[len(data)-1] != '\n' {
238→			b.WriteByte('\n')
239→		}
240→	}
241→	b.WriteString(entry)
242→	b.WriteByte('\n')
243→
244→	if err := os.MkdirAll(filepath.Dir(excludePath), 0o755); err != nil {
245→		return fmt.Errorf("create %s: %w", filepath.Dir(excludePath), err)
246→	}
247→	if err := os.WriteFile(excludePath, []byte(b.String()), 0o644); err != nil {
248→		return fmt.Errorf("write %s: %w", excludePath, err)
249→	}
250→	return nil
251→}
