253→// ForEachAgent runs fn as a parallel subtest for every registered agent.
254→// It handles repo setup, concurrency gating, context timeout, and cleanup.
255→// The timeout is scaled by each agent's TimeoutMultiplier.
256→//
257→// If RunPrompt detects a transient API error (e.g. rate limit, token refresh
258→// failure), it panics with errScenarioRestart. ForEachAgent recovers from the
259→// panic and restarts the entire scenario with a fresh repository, up to
260→// maxScenarioRestarts times. This avoids stale CLI session state from the
261→// failed attempt poisoning the retry.
262→func ForEachAgent(t *testing.T, timeout time.Duration, fn func(t *testing.T, s *RepoState, ctx context.Context)) {
263→	t.Helper()
264→	t.Parallel()
265→	all := agents.All()
266→	if len(all) == 0 {
267→		t.Skip("no agents registered (check E2E_AGENT filter)")
268→	}
269→	for _, agent := range all {
270→		t.Run(agent.Name(), func(t *testing.T) {
271→			// Use the global test deadline for slot wait so we don't
272→			// skip prematurely — only bail if the whole binary is dying.
273→			slotCtx := context.Background()
274→			if deadline, ok := t.Deadline(); ok {
275→				var cancel context.CancelFunc
276→				slotCtx, cancel = context.WithDeadline(slotCtx, deadline)
277→				defer cancel()
278→			}
279→			if err := agents.AcquireSlot(slotCtx, agent); err != nil {
280→				t.Fatalf("timed out waiting for agent slot: %v", err)
281→			}
282→			defer agents.ReleaseSlot(agent)
283→
284→			// Per-test timeout starts after slot is acquired, scaled
285→			// by the agent's multiplier (e.g. 2.5× for gemini).
286→			scaled := time.Duration(float64(timeout) * agent.TimeoutMultiplier())
287→
288→			var prevState *RepoState
289→			for attempt := range maxScenarioRestarts + 1 {
290→				s := SetupRepo(t, agent)
291→				ctx, cancel := context.WithTimeout(context.Background(), scaled)
292→
293→				// On restart, suppress artifact capture from the previous
294→				// failed attempt so it doesn't overwrite the final one.
295→				if prevState != nil {
296→					prevState.skipArtifacts = true
297→				}
298→
299→				restarted := runScenario(t, s, ctx, fn)
300→				cancel()
301→
302→				if !restarted {
303→					return
304→				}
305→				prevState = s
306→				if attempt >= maxScenarioRestarts {
307→					t.Fatalf("exhausted %d scenario attempts due to transient API errors", maxScenarioRestarts+1)
308→				}
309→				t.Logf("transient error, restarting scenario (attempt %d/%d)", attempt+2, maxScenarioRestarts+1)
310→			}
311→		})
312→	}
313→}
314→
315→// runScenario runs the test function and recovers from errScenarioRestart
316→// panics triggered by transient API errors in RunPrompt. Returns true if
317→// the scenario should be restarted with a fresh repository.
318→func runScenario(t *testing.T, s *RepoState, ctx context.Context, fn func(t *testing.T, s *RepoState, ctx context.Context)) (restarted bool) {
319→	t.Helper()
320→	defer func() {
321→		if r := recover(); r != nil {
322→			if _, ok := r.(errScenarioRestart); ok {
323→				restarted = true
324→				return
325→			}
326→			panic(r) // re-panic for unexpected panics
327→		}
328→	}()
329→	fn(t, s, ctx)
330→	return false
331→}
332→
333→const maxScenarioRestarts = 2 // restart up to 2 times = 3 total attempts
334→
335→// errScenarioRestart is panicked by RunPrompt when a transient API error is
336→// detected. ForEachAgent recovers from this panic and restarts the test
337→// scenario with a fresh repository, avoiding stale CLI state from the failed
338→// attempt.
339→type errScenarioRestart struct {
340→	msg string
341→}
342→
343→// RunPrompt runs an agent prompt, logs the command and output to ConsoleLog,
344→// and returns the result. If the agent reports a transient API error, it
345→// panics with errScenarioRestart to trigger a full scenario restart in
346→// ForEachAgent (see runScenario).
347→func (s *RepoState) RunPrompt(t *testing.T, ctx context.Context, prompt string, opts ...agents.Option) (agents.Output, error) {
348→	t.Helper()
349→	out, err := s.Agent.RunPrompt(ctx, s.Dir, prompt, opts...)
350→	s.logPromptResult(out)
351→
352→	if err != nil && s.Agent.IsTransientError(out, err) {
353→		errMsg := fmt.Sprintf("transient API error (stderr: %s)", strings.TrimSpace(out.Stderr))
354→		t.Logf("%s — restarting scenario", errMsg)
355→		fmt.Fprintf(s.ConsoleLog, "> [transient] %s — restarting scenario\n", errMsg)
356→		panic(errScenarioRestart{msg: errMsg})
357→	}
358→
359→	return out, err
360→}
361→
362→func (s *RepoState) logPromptResult(out agents.Output) {
363→	s.ConsoleLog.WriteString("> " + out.Command + "\n")
364→	s.ConsoleLog.WriteString("stdout:\n" + out.Stdout + "\n")
365→	s.ConsoleLog.WriteString("stderr:\n" + out.Stderr + "\n")
366→}
367→
368→// Git runs a git command in the repo and logs it to ConsoleLog.
369→func (s *RepoState) Git(t *testing.T, args ...string) {
370→	t.Helper()
371→	s.ConsoleLog.WriteString("> git " + strings.Join(args, " ") + "\n")
372→	Git(t, s.Dir, args...)
373→}
374→
375→// StartSession starts an interactive session and registers it for pane
376→// capture in artifacts. Returns nil if the agent does not support interactive
377→// mode. The session is closed automatically during test cleanup.
378→func (s *RepoState) StartSession(t *testing.T, ctx context.Context) agents.Session {
379→	t.Helper()
380→	session, err := s.Agent.StartSession(ctx, s.Dir)
381→	if err != nil {
382→		t.Fatalf("start session: %v", err)
383→	}
384→	if session == nil {
385→		return nil
386→	}
387→	s.session = session
388→	return session
