488→// CheckpointIDs lists all checkpoint IDs from the tree at the tip of the
489→// checkpoint branch. It parses the two-level directory structure
490→// ({prefix}/{suffix}/metadata.json) and returns the concatenated IDs.
491→func CheckpointIDs(t *testing.T, dir string) []string {
492→	t.Helper()
493→	out := gitOutputSafe(dir, "ls-tree", "-r", "--name-only", "entire/checkpoints/v1")
494→	if out == "" {
495→		return nil
496→	}
497→	seen := map[string]bool{}
498→	var ids []string
499→	for _, line := range strings.Split(strings.TrimSpace(out), "\n") {
500→		// Match {prefix}/{suffix}/metadata.json (top-level, not session-level)
501→		parts := strings.Split(line, "/")
502→		if len(parts) == 3 && parts[2] == "metadata.json" {
503→			id := parts[0] + parts[1]
504→			if !seen[id] {
505→				seen[id] = true
506→				ids = append(ids, id)
507→			}
508→		}
509→	}
510→	return ids
511→}
