330→func cmdExtractModifiedFiles() {
331→	path := getFlag("--path")
332→	offset, err := strconv.Atoi(getFlag("--offset"))
333→	if err != nil {
334→		fatal("invalid --offset: %v", err)
335→	}
336→
337→	lines := readTranscriptLines(path)
338→	var files []string
339→	seen := map[string]bool{}
340→
341→	for i := offset; i < len(lines); i++ {
342→		var line transcriptLine
343→		if err := json.Unmarshal(lines[i], &line); err != nil {
344→			continue
345→		}
346→		if line.Type != "assistant" {
347→			continue
348→		}
349→		text := extractAssistantText(line.Message)
350→		if m := createdFileRe.FindStringSubmatch(text); m != nil {
351→			f := m[1]
352→			if !seen[f] {
353→				seen[f] = true
354→				files = append(files, f)
355→			}
356→		}
357→	}
358→
359→	writeJSON(map[string]any{
360→		"files":            files,
361→		"current_position": len(lines),
362→	})
363→}
364→
365→func cmdExtractPrompts() {
366→	sessionRef := getFlag("--session-ref")
367→	offset, err := strconv.Atoi(getFlag("--offset"))
368→	if err != nil {
369→		fatal("invalid --offset: %v", err)
370→	}
371→
372→	lines := readTranscriptLines(sessionRef)
373→	var prompts []string
374→
375→	for i := offset; i < len(lines); i++ {
376→		var line transcriptLine
377→		if err := json.Unmarshal(lines[i], &line); err != nil {
378→			continue
379→		}
380→		if line.Type == "user" {
381→			text := extractUserText(line.Message)
382→			if text != "" {
383→				prompts = append(prompts, text)
384→			}
385→		}
386→	}
387→
388→	writeJSON(map[string][]string{"prompts": prompts})
389→}
390→
391→func cmdExtractSummary() {
392→	sessionRef := getFlag("--session-ref")
393→	lines := readTranscriptLines(sessionRef)
394→
395→	var prompts []string
396→	for _, raw := range lines {
397→		var line transcriptLine
398→		if err := json.Unmarshal(raw, &line); err != nil {
399→			continue
400→		}
401→		if line.Type == "user" {
402→			text := extractUserText(line.Message)
403→			if text != "" {
404→				prompts = append(prompts, text)
405→			}
406→		}
407→	}
408→
409→	if len(prompts) == 0 {
410→		writeJSON(map[string]any{"summary": "", "has_summary": false})
411→		return
412→	}
413→
414→	summary := prompts[0]
415→	if len(summary) > 100 {
416→		summary = summary[:100] + "..."
417→	}
418→	writeJSON(map[string]any{"summary": summary, "has_summary": true})
419→}
420→
421→var createdFileRe = regexp.MustCompile(`^Created ([^\s]+)\.$`)
422→
423→// extractUserText extracts the text content from a user message.
424→func extractUserText(raw json.RawMessage) string {
425→	var msg userMessage
426→	if err := json.Unmarshal(raw, &msg); err != nil {
427→		return ""
428→	}
429→	return msg.Content
430→}
431→
432→// extractAssistantText extracts concatenated text from an assistant message's content blocks.
433→func extractAssistantText(raw json.RawMessage) string {
434→	var msg assistantMessage
435→	if err := json.Unmarshal(raw, &msg); err != nil {
436→		return ""
437→	}
438→	var texts []string
439→	for _, block := range msg.Content {
440→		if block.Type == "text" && block.Text != "" {
441→			texts = append(texts, block.Text)
442→		}
443→	}
444→	return strings.Join(texts, "\n")
445→}
446→
447→// readTranscriptLines reads a JSONL file and returns non-empty lines.
448→func readTranscriptLines(path string) [][]byte {
449→	data, err := os.ReadFile(path)
450→	if err != nil {
451→		return nil
452→	}
453→	var lines [][]byte
454→	for _, line := range bytes.Split(data, []byte("\n")) {
455→		if len(bytes.TrimSpace(line)) > 0 {
456→			lines = append(lines, line)
457→		}
458→	}
459→	return lines
460→}
