462→// --- Helpers ---
463→
464→func getFlag(name string) string {
465→	for i := 1; i < len(os.Args)-1; i++ {
466→		if os.Args[i] == name {
467→			return os.Args[i+1]
468→		}
469→	}
470→	fatal("missing required flag: %s", name)
471→	return ""
472→}
473→
474→func writeJSON(v any) {
475→	data, err := json.Marshal(v)
476→	if err != nil {
477→		fatal("marshal JSON: %v", err)
478→	}
479→	os.Stdout.Write(data)
480→}
481→
482→func readJSONStdin(v any) {
483→	data, err := io.ReadAll(os.Stdin)
484→	if err != nil {
485→		fatal("read stdin: %v", err)
486→	}
487→	if len(data) == 0 {
488→		fatal("empty stdin")
489→	}
490→	if err := json.Unmarshal(data, v); err != nil {
491→		fatal("parse JSON: %v", err)
492→	}
493→}
494→
495→func chunkJSONL(data []byte, maxSize int) [][]byte {
496→	if len(data) == 0 {
497→		return nil
498→	}
499→	if maxSize <= 0 || len(data) <= maxSize {
500→		return [][]byte{data}
501→	}
502→	var chunks [][]byte
503→	var current []byte
504→	for _, line := range bytes.Split(data, []byte("\n")) {
505→		if len(line) == 0 {
506→			continue
507→		}
508→		lineWithNewline := append(line, '\n')
509→		if len(current)+len(lineWithNewline) > maxSize && len(current) > 0 {
510→			chunks = append(chunks, current)
511→			current = nil
512→		}
513→		current = append(current, lineWithNewline...)
514→	}
515→	if len(current) > 0 {
516→		chunks = append(chunks, current)
517→	}
518→	return chunks
519→}
