  56→			if settings.StrategyOptions == nil {
  57→				settings.StrategyOptions = make(map[string]interface{})
  58→			}
  59→			settings.StrategyOptions["checkpoint_remote"] = map[string]any{
  60→				"provider": provider,
  61→				"repo":     repo,
  62→			}
  63→		}
  64→	}
  65→}
  66→
  67→// parseCheckpointRemoteFlag parses a "provider:owner/repo" string into its components.
  68→// Supported providers: "github".
  69→func parseCheckpointRemoteFlag(value string) (provider, repo string, err error) {
  70→	parts := strings.SplitN(value, ":", 2)
  71→	if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
  72→		return "", "", fmt.Errorf("expected format provider:owner/repo (e.g., github:org/checkpoints-repo), got %q", value)
  73→	}
  74→
  75→	provider = parts[0]
  76→	repo = parts[1]
  77→
  78→	switch provider {
  79→	case "github":
  80→		// valid
  81→	default:
  82→		return "", "", fmt.Errorf("unsupported provider %q (supported: github)", provider)
  83→	}
  84→
  85→	repoParts := strings.SplitN(repo, "/", 2)
  86→	if len(repoParts) != 2 || repoParts[0] == "" || repoParts[1] == "" {
  87→		return "", "", fmt.Errorf("repo must be in owner/name format, got %q", repo)
  88→	}
  89→
  90→	return provider, repo, nil
  91→}
