  97→
  98→	cmd := &cobra.Command{
  99→		Use:   "enable",
 100→		Short: "Enable Entire in current project",
 101→		Long: `Enable Entire with session tracking for your AI agent workflows.
 102→
 103→Uses the manual-commit strategy, which creates session checkpoints without
 104→modifying your active branch.`,
 105→		RunE: func(cmd *cobra.Command, _ []string) error {
 106→			ctx := cmd.Context()
 107→			// Check if we're in a git repository first - this is a prerequisite error,
 108→			// not a usage error, so we silence Cobra's output and use SilentError
 109→			// to prevent duplicate error output in main.go
 110→			if _, err := paths.WorktreeRoot(ctx); err != nil {
 111→				fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run 'entire enable' from within a git repository.")
 112→				return NewSilentError(errors.New("not a git repository"))
 113→			}
 114→
 115→			if err := validateSetupFlags(opts.UseLocalSettings, opts.UseProjectSettings); err != nil {
