 121→
 122→			// Warn if repo has no commits yet
 123→			if repo, err := strategy.OpenRepository(ctx); err == nil && strategy.IsEmptyRepository(repo) {
 124→				fmt.Fprintln(cmd.OutOrStdout(), "Note: This repository has no commits yet. Entire will be configured, but")
 125→				fmt.Fprintln(cmd.OutOrStdout(), "session checkpoints won't work until you create your first commit.")
 126→				fmt.Fprintln(cmd.OutOrStdout())
