 221→// runEnableInteractive runs the interactive enable flow.
 222→// agents must be provided by the caller (via detectOrSelectAgent).
 223→func runEnableInteractive(ctx context.Context, w io.Writer, agents []agent.Agent, opts EnableOptions) error {
 224→	// Uninstall hooks for agents that were previously active but are no longer selected
 225→	if err := uninstallDeselectedAgentHooks(ctx, w, agents); err != nil {
 226→		return fmt.Errorf("failed to clean up deselected agents: %w", err)
 227→	}
 228→
 229→	// Setup agent hooks for all selected agents
 230→	for _, ag := range agents {
 231→		if _, err := setupAgentHooks(ctx, ag, opts.LocalDev, opts.ForceHooks); err != nil {
 232→			return fmt.Errorf("failed to setup %s hooks: %w", ag.Type(), err)
 233→		}
 234→	}
 235→
 236→	// Setup .entire directory
 237→	if _, err := setupEntireDirectory(ctx); err != nil {
 238→		return fmt.Errorf("failed to setup .entire directory: %w", err)
 239→	}
 240→
 241→	// Load existing settings to preserve other options (like strategy_options.push)
 242→	settings, err := LoadEntireSettings(ctx)
 243→	if err != nil {
 244→		// If we can't load, start with defaults
 245→		settings = &EntireSettings{}
 246→	}
 247→	// Update the specific fields
 248→	settings.Enabled = true
 249→	if opts.LocalDev {
 250→		settings.LocalDev = true
 251→	}
 252→	if opts.AbsoluteGitHookPath {
 253→		settings.AbsoluteGitHookPath = true
 254→	}
 255→
 256→	opts.applyStrategyOptions(settings)
 257→
 258→	// Determine which settings file to write to
 259→	// First run always creates settings.json (no prompt)
 260→	entireDirAbs, err := paths.AbsPath(ctx, paths.EntireDir)
 261→	if err != nil {
 262→		entireDirAbs = paths.EntireDir // Fallback to relative
 263→	}
 264→	shouldUseLocal, showNotification := determineSettingsTarget(entireDirAbs, opts.UseLocalSettings, opts.UseProjectSettings)
 265→
 266→	if showNotification {
 267→		fmt.Fprintln(w, "Info: Project settings exist. Saving to settings.local.json instead.")
 268→		fmt.Fprintln(w, "  Use --project to update the project settings file.")
 269→	}
 270→
 271→	// Save settings to the appropriate file.
 272→	saveSettings := func() error {
 273→		if shouldUseLocal {
 274→			return SaveEntireSettingsLocal(ctx, settings)
 275→		}
 276→		return SaveEntireSettings(ctx, settings)
 277→	}
 278→	if err := saveSettings(); err != nil {
 279→		return fmt.Errorf("failed to save settings: %w", err)
 280→	}
 281→
 282→	// Use settings values (merged from existing config + flags) for hook installation
 283→	// This ensures re-running `entire enable` without flags preserves existing settings
 284→	if _, err := strategy.InstallGitHook(ctx, true, settings.LocalDev, settings.AbsoluteGitHookPath); err != nil {
 285→		return fmt.Errorf("failed to install git hooks: %w", err)
 286→	}
 287→	strategy.CheckAndWarnHookManagers(ctx, w, settings.LocalDev, settings.AbsoluteGitHookPath)
 288→	fmt.Fprintln(w, "✓ Hooks installed")
 289→
 290→	configDisplay := configDisplayProject
 291→	if shouldUseLocal {
 292→		configDisplay = configDisplayLocal
 293→	}
 294→	fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplay)
 295→
 296→	// Ask about telemetry consent (only if not already asked)
 297→	fmt.Fprintln(w)
 298→	if err := promptTelemetryConsent(settings, opts.Telemetry); err != nil {
 299→		return fmt.Errorf("telemetry consent: %w", err)
 300→	}
 301→	// Save again to persist telemetry choice
 302→	if err := saveSettings(); err != nil {
 303→		return fmt.Errorf("failed to save settings: %w", err)
 304→	}
 305→
 306→	if err := strategy.EnsureSetup(ctx); err != nil {
 307→		return fmt.Errorf("failed to setup strategy: %w", err)
 308→	}
 309→
 310→	fmt.Fprintln(w, "\nReady.")
 311→
 312→	return nil
 313→}
