 358→// checkDisabledGuard checks if Entire is disabled and prints a message if so.
 359→// Returns true if the caller should exit (i.e., Entire is disabled).
 360→// On error reading settings, defaults to enabled (returns false).
 361→func checkDisabledGuard(ctx context.Context, w io.Writer) bool {
 362→	enabled, err := IsEnabled(ctx)
 363→	if err != nil {
 364→		// Default to enabled on error
 365→		return false
 366→	}
 367→	if !enabled {
 368→		fmt.Fprintln(w, DisabledMessage)
 369→		return true
 370→	}
 371→	return false
