 374→// uninstallDeselectedAgentHooks removes hooks for agents that were previously
 375→// installed but are not in the selected list. This handles the case where a user
 376→// re-runs `entire enable` and deselects an agent.
 377→func uninstallDeselectedAgentHooks(ctx context.Context, w io.Writer, selectedAgents []agent.Agent) error {
 378→	installedNames := GetAgentsWithHooksInstalled(ctx)
 379→	if len(installedNames) == 0 {
 380→		return nil
 381→	}
 382→
 383→	selectedSet := make(map[types.AgentName]struct{}, len(selectedAgents))
 384→	for _, ag := range selectedAgents {
 385→		selectedSet[ag.Name()] = struct{}{}
 386→	}
 387→
 388→	var errs []error
 389→	for _, name := range installedNames {
 390→		if _, selected := selectedSet[name]; selected {
 391→			continue
 392→		}
 393→		ag, err := agent.Get(name)
 394→		if err != nil {
 395→			continue
 396→		}
 397→		hookAgent, ok := agent.AsHookSupport(ag)
 398→		if !ok {
 399→			continue
 400→		}
 401→		if err := hookAgent.UninstallHooks(ctx); err != nil {
 402→			errs = append(errs, fmt.Errorf("failed to uninstall %s hooks: %w", ag.Type(), err))
 403→		} else {
 404→			fmt.Fprintf(w, "Removed %s hooks\n", ag.Type())
 405→		}
 406→	}
 407→	return errors.Join(errs...)
 408→}
