 410→// setupAgentHooks sets up hooks for a given agent.
 411→// Returns the number of hooks installed (0 if already installed).
 412→func setupAgentHooks(ctx context.Context, ag agent.Agent, localDev, forceHooks bool) (int, error) {
 413→	hookAgent, ok := agent.AsHookSupport(ag)
 414→	if !ok {
 415→		return 0, fmt.Errorf("agent %s does not support hooks", ag.Name())
 416→	}
 417→
 418→	count, err := hookAgent.InstallHooks(ctx, localDev, forceHooks)
 419→	if err != nil {
 420→		return 0, fmt.Errorf("failed to install %s hooks: %w", ag.Name(), err)
 421→	}
 422→
 423→	return count, nil
 424→}
