 426→// detectOrSelectAgent tries to auto-detect agents, or prompts the user to select.
 427→// Returns the detected/selected agents and any error.
 428→//
 429→// On first run (no hooks installed):
 430→//   - Single detected agent: used automatically
 431→//   - Multiple/no detected agents: interactive multi-select prompt
 432→//
 433→// On re-run (hooks already installed):
 434→//   - Always shows the interactive multi-select
 435→//   - Pre-selects only agents that have hooks installed (respects prior deselection)
 436→//
 437→// selectFn overrides the interactive prompt for testing. When nil, the real form is used.
 438→// It receives available agent names and returns the selected names.
 439→func detectOrSelectAgent(ctx context.Context, w io.Writer, selectFn func(available []string) ([]string, error)) ([]agent.Agent, error) {
 440→	// Check for agents with hooks already installed (re-run detection)
 441→	installedAgentNames := GetAgentsWithHooksInstalled(ctx)
 442→	hasInstalledHooks := len(installedAgentNames) > 0
 443→
 444→	// Try auto-detection
 445→	detected := agent.DetectAll(ctx)
 446→
 447→	// First run: use existing auto-detect shortcuts
 448→	if !hasInstalledHooks {
 449→		switch {
 450→		case len(detected) == 1:
 451→			fmt.Fprintf(w, "Detected agent: %s\n\n", detected[0].Type())
 452→			return detected, nil
 453→
 454→		case len(detected) > 1:
 455→			agentTypes := make([]string, 0, len(detected))
 456→			for _, ag := range detected {
 457→				agentTypes = append(agentTypes, string(ag.Type()))
 458→			}
 459→			fmt.Fprintf(w, "Detected multiple agents: %s\n", strings.Join(agentTypes, ", "))
 460→			fmt.Fprintln(w)
 461→		}
 462→	}
 463→
 464→	// Check if we can prompt interactively
 465→	if !canPromptInteractively() {
 466→		if hasInstalledHooks {
 467→			// Re-run without TTY — keep currently installed agents
 468→			agents := make([]agent.Agent, 0, len(installedAgentNames))
 469→			for _, name := range installedAgentNames {
 470→				ag, err := agent.Get(name)
 471→				if err != nil {
 472→					continue
 473→				}
 474→				agents = append(agents, ag)
 475→			}
 476→			return agents, nil
 477→		}
 478→		if len(detected) > 0 {
 479→			return detected, nil
 480→		}
 481→		defaultAgent := agent.Default()
 482→		if defaultAgent == nil {
 483→			return nil, errors.New("no default agent available")
 484→		}
 485→		fmt.Fprintf(w, "Agent: %s (use --agent to change)\n\n", defaultAgent.Type())
 486→		return []agent.Agent{defaultAgent}, nil
 487→	}
 488→
 489→	if !hasInstalledHooks && len(detected) == 0 {
 490→		fmt.Fprintln(w, "No agent configuration detected (e.g., "+strings.Join(agent.StringList(), ", ")+").")
 491→		fmt.Fprintln(w, "This is normal - some agents don't require a config directory.")
 492→		fmt.Fprintln(w)
 493→	}
 494→
 495→	// Build pre-selection set.
 496→	// On re-run: only pre-select agents with hooks installed (respect prior deselection).
 497→	// On first run: pre-select all detected agents.
 498→	preSelectedSet := make(map[types.AgentName]struct{})
 499→	if hasInstalledHooks {
 500→		for _, name := range installedAgentNames {
 501→			preSelectedSet[name] = struct{}{}
 502→		}
 503→	} else {
 504→		for _, ag := range detected {
 505→			preSelectedSet[ag.Name()] = struct{}{}
 506→		}
 507→	}
 508→
 509→	// Build options from registered agents
 510→	agentNames := agent.List()
 511→	options := make([]huh.Option[string], 0, len(agentNames))
 512→	for _, name := range agentNames {
 513→		ag, err := agent.Get(name)
 514→		if err != nil {
 515→			continue
 516→		}
 517→		// Only show agents that support hooks
 518→		if _, ok := agent.AsHookSupport(ag); !ok {
 519→			continue
 520→		}
 521→		// Skip test-only agents (e.g., Vogon canary)
 522→		if to, ok := ag.(agent.TestOnly); ok && to.IsTestOnly() {
 523→			continue
 524→		}
 525→		opt := huh.NewOption(string(ag.Type()), string(name))
 526→		if _, isPreSelected := preSelectedSet[name]; isPreSelected {
 527→			opt = opt.Selected(true)
 528→		}
 529→		options = append(options, opt)
 530→	}
 531→
 532→	if len(options) == 0 {
 533→		return nil, errors.New("no agents with hook support available")
 534→	}
 535→
 536→	// Collect available agent names for the selector
 537→	availableNames := make([]string, 0, len(options))
 538→	for _, opt := range options {
 539→		availableNames = append(availableNames, opt.Value)
 540→	}
 541→
 542→	var selectedAgentNames []string
 543→	if selectFn != nil {
 544→		var err error
 545→		selectedAgentNames, err = selectFn(availableNames)
 546→		if err != nil {
 547→			return nil, err
 548→		}
 549→		if len(selectedAgentNames) == 0 {
 550→			return nil, errors.New("no agents selected")
 551→		}
 552→	} else {
 553→		form := NewAccessibleForm(
 554→			huh.NewGroup(
 555→				huh.NewMultiSelect[string]().
 556→					Title("Which agents are you using?").
 557→					Description("Use space to select, enter to confirm.").
 558→					Options(options...).
 559→					Validate(func(selected []string) error {
 560→						if len(selected) == 0 {
 561→							return errors.New("please select at least one agent")
 562→						}
 563→						return nil
 564→					}).
 565→					Value(&selectedAgentNames),
 566→			),
 567→		)
 568→		if err := form.Run(); err != nil {
 569→			return nil, fmt.Errorf("agent selection cancelled: %w", err)
 570→		}
 571→	}
 572→
 573→	selectedAgents := make([]agent.Agent, 0, len(selectedAgentNames))
 574→	for _, name := range selectedAgentNames {
 575→		selectedAgent, err := agent.Get(types.AgentName(name))
 576→		if err != nil {
 577→			return nil, fmt.Errorf("failed to get selected agent %s: %w", name, err)
 578→		}
 579→		selectedAgents = append(selectedAgents, selectedAgent)
 580→	}
 581→
 582→	agentTypes := make([]string, 0, len(selectedAgents))
 583→	for _, ag := range selectedAgents {
 584→		agentTypes = append(agentTypes, string(ag.Type()))
 585→	}
 586→	fmt.Fprintf(w, "\nSelected agents: %s\n\n", strings.Join(agentTypes, ", "))
 587→	return selectedAgents, nil
 588→}
