 590→// canPromptInteractively checks if we can show interactive prompts.
 591→// Returns false when running in CI, tests, or other non-interactive environments.
 592→func canPromptInteractively() bool {
 593→	// Check for test environment
 594→	if os.Getenv("ENTIRE_TEST_TTY") != "" {
 595→		return os.Getenv("ENTIRE_TEST_TTY") == "1"
 596→	}
 597→
 598→	// Check if /dev/tty is available
 599→	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
 600→	if err != nil {
 601→		return false
 602→	}
 603→	_ = tty.Close()
 604→	return true
 605→}
