 633→// setupAgentHooksNonInteractive sets up hooks for a specific agent non-interactively.
 634→// If strategyName is provided, it sets the strategy; otherwise uses default.
 635→func setupAgentHooksNonInteractive(ctx context.Context, w io.Writer, ag agent.Agent, opts EnableOptions) error {
 636→	agentName := ag.Name()
 637→	// Check if agent supports hooks
 638→	hookAgent, ok := agent.AsHookSupport(ag)
 639→	if !ok {
 640→		return fmt.Errorf("agent %s does not support hooks", agentName)
 641→	}
 642→
 643→	fmt.Fprintf(w, "Agent: %s\n\n", ag.Type())
 644→
 645→	// Install agent hooks (agent hooks don't depend on settings)
 646→	installedHooks, err := hookAgent.InstallHooks(ctx, opts.LocalDev, opts.ForceHooks)
 647→	if err != nil {
 648→		return fmt.Errorf("failed to install hooks for %s: %w", agentName, err)
 649→	}
 650→
 651→	// Setup .entire directory
 652→	if _, err := setupEntireDirectory(ctx); err != nil {
 653→		return fmt.Errorf("failed to setup .entire directory: %w", err)
 654→	}
 655→
 656→	// Load existing settings to preserve other options (like strategy_options.push)
 657→	settings, err := LoadEntireSettings(ctx)
 658→	if err != nil {
 659→		// If we can't load, start with defaults
 660→		settings = &EntireSettings{}
 661→	}
 662→	settings.Enabled = true
 663→	if opts.LocalDev {
 664→		settings.LocalDev = true
 665→	}
 666→	if opts.AbsoluteGitHookPath {
 667→		settings.AbsoluteGitHookPath = true
 668→	}
 669→
 670→	opts.applyStrategyOptions(settings)
 671→
 672→	// Handle telemetry for non-interactive mode
 673→	// Note: if telemetry is nil (not configured), it defaults to disabled
 674→	if !opts.Telemetry || os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
 675→		f := false
 676→		settings.Telemetry = &f
 677→	}
 678→
 679→	if err := SaveEntireSettings(ctx, settings); err != nil {
 680→		return fmt.Errorf("failed to save settings: %w", err)
 681→	}
 682→
 683→	// Use settings values (merged from existing config + flags) for hook installation
 684→	// This ensures re-running `entire enable --agent X` without flags preserves existing settings
 685→	if _, err := strategy.InstallGitHook(ctx, true, settings.LocalDev, settings.AbsoluteGitHookPath); err != nil {
 686→		return fmt.Errorf("failed to install git hooks: %w", err)
 687→	}
 688→	strategy.CheckAndWarnHookManagers(ctx, w, settings.LocalDev, settings.AbsoluteGitHookPath)
 689→
 690→	if installedHooks == 0 {
 691→		msg := fmt.Sprintf("Hooks for %s already installed", ag.Description())
 692→		if ag.IsPreview() {
 693→			msg += " (Preview)"
 694→		}
 695→		fmt.Fprintf(w, "%s\n", msg)
 696→	} else {
 697→		msg := fmt.Sprintf("Installed %d hooks for %s", installedHooks, ag.Description())
 698→		if ag.IsPreview() {
 699→			msg += " (Preview)"
 700→		}
 701→		fmt.Fprintf(w, "%s\n", msg)
 702→	}
 703→
 704→	fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplayProject)
 705→
 706→	if err := strategy.EnsureSetup(ctx); err != nil {
 707→		return fmt.Errorf("failed to setup strategy: %w", err)
 708→	}
 709→
 710→	fmt.Fprintln(w, "\nReady.")
 711→
 712→	return nil
 713→}
