 825→// shellCompletionTarget returns the rc file path and completion lines for the
 826→// user's current shell.
 827→func shellCompletionTarget() (shellName, rcFile, completionLine string, err error) {
 828→	home, err := os.UserHomeDir()
 829→	if err != nil {
 830→		return "", "", "", fmt.Errorf("cannot determine home directory: %w", err)
 831→	}
 832→
 833→	shell := os.Getenv("SHELL")
 834→	switch {
 835→	case strings.Contains(shell, "zsh"):
 836→		return "Zsh",
 837→			filepath.Join(home, ".zshrc"),
 838→			"autoload -Uz compinit && compinit && source <(entire completion zsh)",
 839→			nil
 840→	case strings.Contains(shell, "bash"):
 841→		bashRC := filepath.Join(home, ".bashrc")
 842→		if _, err := os.Stat(filepath.Join(home, ".bash_profile")); err == nil {
 843→			bashRC = filepath.Join(home, ".bash_profile")
 844→		}
 845→		return "Bash",
 846→			bashRC,
 847→			"source <(entire completion bash)",
 848→			nil
 849→	case strings.Contains(shell, "fish"):
 850→		return "Fish",
 851→			filepath.Join(home, ".config", "fish", "config.fish"),
 852→			"entire completion fish | source",
 853→			nil
 854→	default:
 855→		return "", "", "", errUnsupportedShell
 856→	}
 857→}
