 859→// promptShellCompletion offers to add shell completion to the user's rc file.
 860→// Only prompts if completion is not already configured.
 861→func promptShellCompletion(w io.Writer) error {
 862→	shellName, rcFile, completionLine, err := shellCompletionTarget()
 863→	if err != nil {
 864→		if errors.Is(err, errUnsupportedShell) {
 865→			fmt.Fprintf(w, "Note: Shell completion not available for your shell. Supported: zsh, bash, fish.\n")
 866→			return nil
 867→		}
 868→		return fmt.Errorf("shell completion: %w", err)
 869→	}
 870→
 871→	if isCompletionConfigured(rcFile) {
 872→		fmt.Fprintf(w, "✓ Shell completion already configured in %s\n", rcFile)
 873→		return nil
 874→	}
 875→
 876→	var selected string
 877→	form := NewAccessibleForm(
 878→		huh.NewGroup(
 879→			huh.NewSelect[string]().
 880→				Title(fmt.Sprintf("Enable shell completion? (detected: %s)", shellName)).
 881→				Options(
 882→					huh.NewOption("Yes", "yes"),
 883→					huh.NewOption("No", "no"),
 884→				).
 885→				Value(&selected),
 886→		),
 887→	)
 888→
 889→	if err := form.Run(); err != nil {
 890→		//nolint:nilerr // User cancelled - not a fatal error, just skip
 891→		return nil
 892→	}
 893→
 894→	if selected != "yes" {
 895→		return nil
 896→	}
 897→
 898→	if err := appendShellCompletion(rcFile, completionLine); err != nil {
 899→		return fmt.Errorf("failed to update %s: %w", rcFile, err)
 900→	}
 901→
 902→	fmt.Fprintf(w, "✓ Shell completion added to %s\n", rcFile)
 903→	fmt.Fprintln(w, "  Restart your shell to activate")
 904→
 905→	return nil
 906→}
