 908→// isCompletionConfigured checks if shell completion is already in the rc file.
 909→func isCompletionConfigured(rcFile string) bool {
 910→	//nolint:gosec // G304: rcFile is constructed from home dir + known filename, not user input
 911→	content, err := os.ReadFile(rcFile)
 912→	if err != nil {
 913→		return false // File doesn't exist or can't read, treat as not configured
 914→	}
 915→	return strings.Contains(string(content), "entire completion")
 916→}
