 918→// appendShellCompletion adds the completion line to the rc file.
 919→func appendShellCompletion(rcFile, completionLine string) error {
 920→	if err := os.MkdirAll(filepath.Dir(rcFile), 0o700); err != nil {
 921→		return fmt.Errorf("creating directory: %w", err)
 922→	}
 923→	//nolint:gosec // G302: Shell rc files need 0644 for user readability
 924→	f, err := os.OpenFile(rcFile, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
 925→	if err != nil {
 926→		return fmt.Errorf("opening file: %w", err)
 927→	}
 928→	defer f.Close()
 929→
 930→	_, err = f.WriteString("\n" + shellCompletionComment + "\n" + completionLine + "\n")
 931→	if err != nil {
 932→		return fmt.Errorf("writing completion: %w", err)
 933→	}
 934→	return nil
 935→}
