 980→// runUninstall completely removes Entire from the repository.
 981→func runUninstall(ctx context.Context, w, errW io.Writer, force bool) error {
 982→	// Check if we're in a git repository
 983→	if _, err := paths.WorktreeRoot(ctx); err != nil {
 984→		fmt.Fprintln(errW, "Not a git repository. Nothing to uninstall.")
 985→		return NewSilentError(errors.New("not a git repository"))
 986→	}
 987→
 988→	// Gather counts for display
 989→	sessionStateCount := countSessionStates(ctx)
 990→	shadowBranchCount := countShadowBranches(ctx)
 991→	gitHooksInstalled := strategy.IsGitHookInstalled(ctx)
 992→	agentsWithInstalledHooks := GetAgentsWithHooksInstalled(ctx)
 993→	entireDirExists := checkEntireDirExists(ctx)
 994→
 995→	// Check if there's anything to uninstall
 996→	if !entireDirExists && !gitHooksInstalled && sessionStateCount == 0 &&
 997→		shadowBranchCount == 0 && len(agentsWithInstalledHooks) == 0 {
 998→		fmt.Fprintln(w, "Entire is not installed in this repository.")
 999→		return nil
1000→	}
1001→
1002→	// Show confirmation prompt unless --force
1003→	if !force {
1004→		fmt.Fprintln(w, "\nThis will completely remove Entire from this repository:")
1005→		if entireDirExists {
1006→			fmt.Fprintln(w, "  - .entire/ directory")
1007→		}
1008→		if gitHooksInstalled {
1009→			fmt.Fprintln(w, "  - Git hooks (prepare-commit-msg, commit-msg, post-commit, pre-push)")
1010→		}
1011→		if sessionStateCount > 0 {
1012→			fmt.Fprintf(w, "  - Session state files (%d)\n", sessionStateCount)
1013→		}
1014→		if shadowBranchCount > 0 {
1015→			fmt.Fprintf(w, "  - Shadow branches (%d)\n", shadowBranchCount)
1016→		}
1017→		if len(agentsWithInstalledHooks) > 0 {
1018→			displayNames := make([]string, 0, len(agentsWithInstalledHooks))
1019→			for _, name := range agentsWithInstalledHooks {
1020→				if ag, err := agent.Get(name); err == nil {
1021→					displayNames = append(displayNames, string(ag.Type()))
1022→				}
1023→			}
1024→			fmt.Fprintf(w, "  - Agent hooks (%s)\n", strings.Join(displayNames, ", "))
1025→		}
1026→		fmt.Fprintln(w)
1027→
1028→		var confirmed bool
1029→		form := NewAccessibleForm(
1030→			huh.NewGroup(
1031→				huh.NewConfirm().
1032→					Title("Are you sure you want to uninstall Entire?").
1033→					Affirmative("Yes, uninstall").
1034→					Negative("Cancel").
1035→					Value(&confirmed),
1036→			),
1037→		)
1038→
1039→		if err := form.Run(); err != nil {
1040→			return fmt.Errorf("confirmation cancelled: %w", err)
1041→		}
1042→
1043→		if !confirmed {
1044→			fmt.Fprintln(w, "Uninstall cancelled.")
1045→			return nil
1046→		}
1047→	}
1048→
1049→	fmt.Fprintln(w, "\nUninstalling Entire CLI...")
1050→
1051→	// 1. Remove agent hooks (lowest risk)
1052→	if err := removeAgentHooks(ctx, w); err != nil {
1053→		fmt.Fprintf(errW, "Warning: failed to remove agent hooks: %v\n", err)
1054→	}
1055→
1056→	// 2. Remove git hooks
1057→	removed, err := strategy.RemoveGitHook(ctx)
1058→	if err != nil {
1059→		fmt.Fprintf(errW, "Warning: failed to remove git hooks: %v\n", err)
1060→	} else if removed > 0 {
1061→		fmt.Fprintf(w, "  Removed git hooks (%d)\n", removed)
1062→	}
1063→
1064→	// 3. Remove session state files
1065→	statesRemoved, err := removeAllSessionStates(ctx)
1066→	if err != nil {
1067→		fmt.Fprintf(errW, "Warning: failed to remove session states: %v\n", err)
1068→	} else if statesRemoved > 0 {
1069→		fmt.Fprintf(w, "  Removed session states (%d)\n", statesRemoved)
1070→	}
1071→
1072→	// 4. Remove .entire/ directory
1073→	if err := removeEntireDirectory(ctx); err != nil {
1074→		fmt.Fprintf(errW, "Warning: failed to remove .entire directory: %v\n", err)
1075→	} else if entireDirExists {
1076→		fmt.Fprintln(w, "  Removed .entire directory")
1077→	}
1078→
1079→	// 5. Remove shadow branches
1080→	branchesRemoved, err := removeAllShadowBranches(ctx)
1081→	if err != nil {
1082→		fmt.Fprintf(errW, "Warning: failed to remove shadow branches: %v\n", err)
1083→	} else if branchesRemoved > 0 {
1084→		fmt.Fprintf(w, "  Removed %d shadow branches\n", branchesRemoved)
1085→	}
1086→
1087→	fmt.Fprintln(w, "\nEntire CLI uninstalled successfully.")
1088→	return nil
1089→}
